#include <torch/extension.h>
#include <c10/hip/HIPStream.h>
#include <hip/hip_runtime.h>
#include <rocwmma/rocwmma.hpp>

__global__ void rocwmma_matmul_kernel(const rocwmma::float16_t* a, const rocwmma::float16_t* b, float* output) {
    using FragmentA = rocwmma::fragment<rocwmma::matrix_a, 16, 16, 16, rocwmma::float16_t, rocwmma::row_major>;
    using FragmentB = rocwmma::fragment<rocwmma::matrix_b, 16, 16, 16, rocwmma::float16_t, rocwmma::row_major>;
    using FragmentC = rocwmma::fragment<rocwmma::accumulator, 16, 16, 16, float>;
    FragmentA fragment_a;
    FragmentB fragment_b;
    FragmentC fragment_c;
    FragmentC fragment_d;
    rocwmma::load_matrix_sync(fragment_a, a, 16);
    rocwmma::load_matrix_sync(fragment_b, b, 16);
    rocwmma::fill_fragment(fragment_c, 0.0f);
    rocwmma::mma_sync(fragment_d, fragment_a, fragment_b, fragment_c);
    rocwmma::store_matrix_sync(output, fragment_d, 16, rocwmma::mem_row_major);
}

torch::Tensor run(const torch::Tensor& a, const torch::Tensor& b) {
    TORCH_CHECK(a.is_cuda() && b.is_cuda(), "inputs must be HIP tensors");
    TORCH_CHECK(a.scalar_type() == torch::kFloat16 && b.scalar_type() == torch::kFloat16, "inputs must be float16");
    TORCH_CHECK(a.is_contiguous() && b.is_contiguous(), "inputs must be contiguous");
    TORCH_CHECK(a.sizes() == torch::IntArrayRef({16, 16}) && b.sizes() == torch::IntArrayRef({16, 16}), "inputs must be 16x16");
    auto output = torch::empty({16, 16}, a.options().dtype(torch::kFloat32));
    rocwmma_matmul_kernel<<<1, 32, 0, c10::hip::getCurrentHIPStream()>>>(
        reinterpret_cast<const rocwmma::float16_t*>(a.data_ptr<at::Half>()),
        reinterpret_cast<const rocwmma::float16_t*>(b.data_ptr<at::Half>()),
        output.data_ptr<float>());
    TORCH_CHECK(hipGetLastError() == hipSuccess, "rocWMMA matmul launch failed");
    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, module) {
    module.def("run", &run, "gfx1200 rocWMMA 16x16 matmul");
}
